const input = $input.first().json;
const body = input.body || input;

const email = body.email;
if (!email) return [{ json: { error: true, message: 'Email required' } }];

// Valid preference categories
const validCategories = ['marketing', 'product_updates', 'newsletter', 'promotions', 'events', 'seo_reports'];

const preferences = {};
for (const cat of validCategories) {
  if (body.preferences && body.preferences[cat] !== undefined) {
    preferences[cat] = Boolean(body.preferences[cat]);
  }
}

return [{
  json: {
    email: email,
    preferences: preferences,
    frequency: body.frequency || 'weekly', // daily, weekly, monthly, never
    action: 'update_preferences'
  }
}];

const input = $input.first().json;
const body = input.body || input;

const email = body.email;
if (!email) return [{ json: { error: true, message: 'Email required' } }];

return [{
  json: {
    email: email,
    reason: body.reason || 'not_specified',
    feedback: body.feedback || '',
    unsubscribe_from: body.unsubscribe_from || 'all', // all, marketing, newsletter
    action: 'unsubscribe'
  }
}];
